"""Offline desktop interface for the MobileNetV3 leaf classifier."""
import argparse
import base64
import io
import sys
import textwrap
import tkinter as tk
import traceback
from pathlib import Path
from tkinter import filedialog, messagebox

from PIL import Image, ImageTk
import torch
from torchvision.transforms import v2

from leaf_severity import condition_type, measure_severity, overlay
from train_plantdoc_mobilenet import IMAGE_MEAN, IMAGE_STD, OUT_ROOT, make_model, padded_box_crop

HERE = Path(__file__).resolve().parent
WEIGHTS = OUT_ROOT / "combined_mobile42_s42" / "best.pt"


# --- look & feel -----------------------------------------------------------
# The wallpaper is built into this file (see the end). If a leaf_background.jpg sits next to
# the script it is used instead, e.g. to swap in a different picture.
WALLPAPER_FILE = HERE / "leaf_background.jpg"
RESAMPLE = getattr(Image, "Resampling", Image).LANCZOS

FALLBACK_BG = "#0f3d33"
CARD_BG, PANEL_BG, LINE = "#ffffff", "#f1f5f3", "#dfe6e2"
INK, MUTED = "#1c2b25", "#6b7a73"
ACCENT, ACCENT_DARK = "#1f6f50", "#175640"
GOOD, BAD, WARN = "#1f6f50", "#b3261e", "#9a6b00"
FONT = "Segoe UI"
WINDOW = (980, 760)
MIN_WINDOW = (920, 740)
MARGIN, GAP = 40, 18             # outer margin / gap between panels: this is the wallpaper you see
PREVIEW = 340                    # square preview area, px

# --- result wording --------------------------------------------------------
BACKGROUND_CLASS = "Background_without_leaves"
HEALTHY_OUT_OF_SCOPE = {"Blueberry___healthy", "Raspberry___healthy", "Soybean___healthy"}
LOW_CONFIDENCE = 0.55


def _sentence(text):
    text = " ".join(text.replace("_", " ").split())
    return text[:1].upper() + text[1:].lower()


def split_class(name):
    """'Apple___Apple_scab' -> ('apple', 'Apple scab'); '...___healthy' -> (crop, None)."""
    crop, _, cond = name.partition("___")
    crop = crop.replace("_", " ").strip()
    if "," in crop:                                   # 'Pepper, bell' -> 'bell pepper'
        head, _, tail = crop.partition(",")
        crop = f"{tail.strip()} {head.strip()}"
    cond = cond.strip()
    if not cond or cond.lower() == "healthy":
        return crop.lower(), None
    # a few labels hold two names separated by a space, e.g. 'Cercospora_leaf_spot Gray_leaf_spot'
    return crop.lower(), " / ".join(_sentence(p) for p in cond.split(" ") if p)


def describe(name, confident=True):
    """Return (headline, notes, kind) for the single top-scoring class; kind: disease/healthy/none."""
    if name == BACKGROUND_CLASS:
        return "No leaf detected in this photo.", ["No supported leaf finding: retake the photograph."], "none"
    crop, condition = split_class(name)
    verb = "is likely" if confident else "may be"
    if condition is None:
        notes = []
        if name in HEALTHY_OUT_OF_SCOPE:
            notes = ["Disease categories for this crop are outside scope. "
                     "This cannot establish that the leaf is healthy."]
        return f"This {crop} leaf {verb} healthy.", notes, "healthy"
    return f"This {crop} leaf {verb} affected by {condition}.", [], "disease"


class FieldAssistant(tk.Tk):
    def __init__(self, classifier_path=WEIGHTS, severity_path=None):
        super().__init__()
        self.title("Agri-SOC Offline Leaf Assistant")
        w, h = WINDOW
        x, y = (self.winfo_screenwidth() - w) // 2, max(0, (self.winfo_screenheight() - h) // 3)
        self.geometry(f"{w}x{h}+{x}+{y}")
        self.minsize(*MIN_WINDOW)
        torch.set_num_threads(min(4, torch.get_num_threads()))
        self.classifier_path = classifier_path or WEIGHTS
        checkpoint = torch.load(self.classifier_path, map_location="cpu", weights_only=True)
        self.classes = checkpoint["classes"]
        self.model = make_model(checkpoint["config"]["backbone"], len(self.classes), pretrained=False).eval()
        self.model.load_state_dict(checkpoint["state"])
        self.normalize = v2.Normalize(IMAGE_MEAN, IMAGE_STD)
        self.severity_model = None
        self.severity_classes = set()
        if severity_path is not None:
            from train_leaf_severity import SeverityNet

            checkpoint = torch.load(severity_path, map_location="cpu", weights_only=True)
            self.severity_model = SeverityNet().eval()
            self.severity_model.load_state_dict(checkpoint["state"])
            self.severity_classes = set(checkpoint["classes"])
            self.severity_input_size = checkpoint.get("severity_input_size", 224)
        self.photo = None
        self.demo_overlay = None
        self.showing_demo_overlay = False
        self._bg_sharp = self._bg_photo = self._bg_after = None
        self._load_background()
        self._build()

    # ---- wallpaper --------------------------------------------------------
    def _load_background(self):
        try:
            if WALLPAPER_FILE.exists():
                self._bg_sharp = Image.open(WALLPAPER_FILE).convert("RGB")
            else:
                self._bg_sharp = Image.open(io.BytesIO(base64.b64decode(_WALLPAPER_B64))).convert("RGB")
        except Exception:
            traceback.print_exc(file=sys.stderr)                    # plain green fallback, app still works

    def _paint_background(self):
        """Scale the wallpaper to cover the window (centre-cropped, never stretched)."""
        self._bg_after = None
        try:
            src = self._bg_sharp
            w, h = self.canvas.winfo_width(), self.canvas.winfo_height()
            if src is None or w < 2 or h < 2:
                return
            sw, sh = src.size
            if w / h > sw / sh:                                     # window is wider than the picture
                cw, ch = sw, sw * h / w
            else:
                cw, ch = sh * w / h, sh
            left, top = (sw - cw) / 2, (sh - ch) / 2
            view = src.crop((int(left), int(top), int(left + cw), int(top + ch))).resize((w, h), RESAMPLE)
            self._bg_photo = ImageTk.PhotoImage(view)
            self.canvas.itemconfigure(self._bg_item, image=self._bg_photo)
        except Exception:
            traceback.print_exc(file=sys.stderr)

    def _schedule_paint(self, delay=80):
        if self._bg_after is not None:
            self.after_cancel(self._bg_after)
        self._bg_after = self.after(delay, self._paint_background)

    def _on_resize(self, _event):
        self._schedule_paint(0 if self._bg_photo is None else 80)

    # ---- layout -----------------------------------------------------------
    def _panel(self, **grid):
        """A white panel placed on the wallpaper; returns the inner frame to fill."""
        outer = tk.Frame(self.canvas, bg=CARD_BG, highlightthickness=1, highlightbackground=LINE)
        outer.grid(**grid)
        inner = tk.Frame(outer, bg=CARD_BG)
        inner.pack(fill="both", expand=True, padx=20, pady=16)
        return inner

    def _build(self):
        cv = self.canvas = tk.Canvas(self, highlightthickness=0, bd=0, bg=FALLBACK_BG)
        cv.pack(fill="both", expand=True)
        cv.grid_propagate(False)
        self._bg_item = cv.create_image(0, 0, anchor="nw")
        cv.bind("<Configure>", self._on_resize)
        cv.grid_columnconfigure(1, weight=1)        # right column takes the spare width
        cv.grid_rowconfigure(1, minsize=190)        # result panel keeps a steady height
        cv.grid_rowconfigure(3, weight=1)           # spare height stays wallpaper

        # title panel
        head = self._panel(row=0, column=0, columnspan=2, sticky="ew", padx=MARGIN, pady=(MARGIN, GAP))
        tk.Label(head, text="Agri-SOC Field Assistant", bg=CARD_BG, fg=INK,
                 font=(FONT, 22, "bold")).pack(anchor="w")
        has_background = BACKGROUND_CLASS in self.classes
        scope = f"{len(self.classes) - int(has_background)} leaf categories"
        if has_background:
            scope += " + background"
        tk.Label(head, text=f"Offline leaf screening  \u00b7  {scope}",
                 bg=CARD_BG, fg=MUTED, font=(FONT, 10)).pack(anchor="w", pady=(2, 0))

        # photo panel: preview + button
        left = self._panel(row=1, column=0, rowspan=3, sticky="nw", padx=(MARGIN, GAP), pady=(0, GAP))
        frame = tk.Frame(left, bg=PANEL_BG, width=PREVIEW, height=PREVIEW,
                         highlightthickness=1, highlightbackground=LINE)
        frame.pack()
        frame.pack_propagate(False)
        self.preview = tk.Label(frame, text="Your leaf photo\nwill appear here", bg=PANEL_BG, fg=MUTED,
                                font=(FONT, 11), justify="center")
        self.preview.pack(expand=True)
        self.preview.bind("<Button-1>", self.toggle_demo_overlay)
        self.button = tk.Button(left, text="Choose leaf photo", command=self.choose, bg=ACCENT, fg="white",
                                activebackground=ACCENT_DARK, activeforeground="white", relief="flat", bd=0,
                                font=(FONT, 11, "bold"), cursor="hand2", pady=9)
        self.button.pack(fill="x", pady=(12, 0))
        self.button.bind("<Enter>", lambda e: self.button.configure(bg=ACCENT_DARK))
        self.button.bind("<Leave>", lambda e: self.button.configure(bg=ACCENT))
        self.status = tk.Label(left, text="No photo selected", bg=CARD_BG, fg=MUTED, font=(FONT, 9), anchor="w")
        self.status.pack(fill="x", pady=(6, 0))

        # result panel
        result = self._panel(row=1, column=1, sticky="nsew", padx=(0, MARGIN), pady=(0, GAP))
        outcome = tk.Text(result, width=8, height=1, bg=CARD_BG, font=(FONT, 9, "bold"),
                          relief="flat", borderwidth=0, highlightthickness=0,
                          padx=2, pady=2, cursor="arrow", takefocus=False)
        blues = ("#0074EC", "#006CDC", "#0063CA", "#0059B6", "#004DA1", "#00408C", "#003577")
        for index, (letter, color) in enumerate(zip("Outcome", blues)):
            tag = f"outcome_blue_{index}"
            outcome.tag_configure(tag, foreground=color)
            outcome.insert("end", letter, tag)
        outcome.configure(state="disabled")
        outcome.pack(anchor="w")
        self.headline = tk.Label(result, text="No image analyzed yet.", bg=CARD_BG, fg=MUTED,
                                 font=(FONT, 16, "bold"), justify="left", anchor="w")
        self.headline.pack(fill="x", pady=(6, 8))
        self.findings = tk.Label(result, text="", bg=CARD_BG, fg="#3b4a43", font=(FONT, 10),
                                 justify="left", anchor="w")
        self.findings.pack(fill="x")

        # guidance panel
        guide = self._panel(row=2, column=1, sticky="new", padx=(0, MARGIN), pady=(0, GAP))
        tk.Label(guide, text="GUIDANCE", bg=CARD_BG, fg=MUTED, font=(FONT, 9, "bold")).pack(anchor="w")
        self.guidance = tk.Label(guide, text=("Use this result as a screening aid. Check the leaf and nearby plants; "
                                              "seek an extension worker when the result is uncertain or symptoms are severe."),
                                 bg=CARD_BG, fg="#3b4a43", font=(FONT, 10), justify="left", anchor="w")
        self.guidance.pack(fill="x", pady=(6, 0))

        # footer panel
        foot = self._panel(row=4, column=0, columnspan=2, sticky="ew", padx=MARGIN, pady=(0, MARGIN))
        tk.Label(foot, text="Runs locally; photos are not uploaded. A low-confidence result needs human review.",
                 bg=CARD_BG, fg=MUTED, font=(FONT, 9)).pack(anchor="w")

        def wrap(label):                                   # keep text wrapped to its panel width
            return lambda event: label.configure(wraplength=max(120, event.width - 4))
        result.bind("<Configure>", lambda e: [l.configure(wraplength=max(120, e.width - 4))
                                              for l in (self.headline, self.findings)])
        guide.bind("<Configure>", wrap(self.guidance))

    # ---- actions ----------------------------------------------------------
    def choose(self):
        path = filedialog.askopenfilename(title="Select a leaf photo", filetypes=[("Image files", "*.jpg *.jpeg *.png *.bmp *.webp")])
        if not path:
            return
        try:
            image = Image.open(path).convert("RGB")
            image.thumbnail((PREVIEW - 12, PREVIEW - 12))
            self.photo = ImageTk.PhotoImage(image)
            self.demo_overlay = None
            self.showing_demo_overlay = False
            self.preview.configure(image=self.photo, text="", cursor="")
            self.status.configure(text=Path(path).name)
            self.analyze(path)
        except Exception as exc:
            messagebox.showerror("Could not read image", str(exc))

    def toggle_demo_overlay(self, _event=None):
        if self.demo_overlay is not None:
            self.showing_demo_overlay = not self.showing_demo_overlay
            self.preview.configure(image=self.demo_overlay if self.showing_demo_overlay else self.photo)

    def show_result(self, headline, notes, color):
        self.headline.configure(text=headline, fg=color, font=(FONT, 18 if color == BAD else 16, "bold"))
        self.findings.configure(text="\n".join(notes))

    def analyze(self, path):
        try:
            crop = padded_box_crop(path).unsqueeze(0).float() / 255
            with torch.inference_mode():
                probs = self.model(self.normalize(crop)).softmax(dim=1)[0]
            best = int(probs.argmax())
            condition = self.classes[best]
            confident = float(probs[best]) >= LOW_CONFIDENCE
            headline, notes, kind = describe(condition, confident)
            lines = list(notes)
            if lines:
                lines.append("")
            lines += ["This is a model estimate, not a diagnosis.",
                      "Use a close-up with one leaf filling the frame."]
            if not confident:
                lines.append("Low score. Retake the photo or ask an extension worker to review it.")
            elif kind == "disease" and self.severity_model is not None:
                note = self.severity_note(condition, crop, float(probs[best]))
                if note:
                    lines.append(note)
            color = WARN if (kind == "none" or not confident) else (GOOD if kind == "healthy" else BAD)
            self.show_result(headline, lines, color)
        except Exception as exc:
            messagebox.showerror("Analysis failed", str(exc))

    def severity_note(self, condition, crop, score):
        kind = condition_type(condition)
        if kind == "pest_damage":
            return "Possible pest damage. Check the underside of the leaf for activity."
        if kind != "disease_symptoms":
            return None
        if condition not in self.severity_classes or score < 0.70:
            return None
        with torch.inference_mode():
            size = (self.severity_input_size, self.severity_input_size)
            inputs = torch.nn.functional.interpolate(crop, size, mode="bilinear", align_corners=False)
            logits = self.severity_model(inputs)
            logits = torch.nn.functional.interpolate(logits, crop.shape[-2:], mode="bilinear", align_corners=False)
            masks = (logits[0] > 0).numpy()
        if self.severity_input_size != 224:
            masks[1] &= masks[0]
        severity = measure_severity(*masks, condition, "experimental_pixel_model")
        if severity["status"] != "measured":
            return None
        percent = severity["visible_affected_pct"]
        band = severity["area_band"]
        rgb = (crop[0].permute(1, 2, 0) * 255).round().byte().numpy()
        tint = overlay(rgb, *masks)
        tint.thumbnail((PREVIEW - 12, PREVIEW - 12))
        self.demo_overlay = ImageTk.PhotoImage(tint)
        self.preview.configure(cursor="hand2")
        return (f"Experimental severity estimate · {percent:.1f}% visible area affected ({band}). "
                "Click the photo to see the overlay.")


