    classifier = args.classifier or WEIGHTS
    if not classifier.is_file():
        parser.error(f"Classifier checkpoint not found: {classifier}")
    if args.severity is not None and not args.severity.is_file():
        parser.error(f"Severity checkpoint not found: {args.severity}")
    FieldAssistant(classifier, args.severity).mainloop()
